// Accepts flat JSON (Tally/Typeform/Webflow/custom forms) or { body: {...} } from the Webhook node.
// Add your own form's field names to the pick() lists if they differ.
const raw = $input.first().json;
const body = raw.body || raw;
const pick = (...keys) => {
  for (const k of keys) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
return [{ json: {
  name: pick('name', 'full_name', 'Name') || 'Unknown',
  email: pick('email', 'Email', 'email_address'),
  company: pick('company', 'company_name', 'Company'),
  website: pick('website', 'url', 'Website'),
  message: pick('message', 'notes', 'details', 'project', 'Message'),
  budget: pick('budget', 'budget_range', 'Budget'),
  timeline: pick('timeline', 'timeframe', 'Timeline'),
  company_size: pick('company_size', 'employees', 'team_size'),
  source: pick('source', 'utm_source') || 'webhook',
  received_at: new Date().toISOString(),
}}];

// ===== EDIT THIS BLOCK TO FIT YOUR BUSINESS =====
const CONFIG = {
  // Words that mean "this is work we actually do". 3+ hits = strong fit.
  fitKeywords: ['website', 'web design', 'redesign', 'branding', 'seo', 'shopify', 'webflow',
                'landing page', 'ui/ux', 'marketing', 'automation', 'n8n'],
  // Phrases that should sink a lead no matter what else it says.
  disqualifiers: ['pro bono', 'no budget', 'equity only', 'student project', 'guest post', 'backlinks'],
  // Budget regexes (tested against message + budget field)
  budgetStrong: [/\$\s?\d{2,3}\s?k/i, /\b\d{2,3}\s?k\b/i, /budget.*(approved|ready|allocated)/i],
  budgetMid: [/\$\s?[2-9]\s?k/i, /\b[2-9]\s?k\b/i, /budget.*(flexible|open)/i, /\$\s?\d,?\d{3}\b/],
  timelineUrgent: [/asap|urgent|this week|this month|by (mon|tue|wed|thu|fri)/i],
  timelineNear: [/next month|this quarter|\bq[1-4]\b|within \d+ weeks?/i],
  timelineCold: [/no rush|someday|just exploring|just curious|next year/i],
  // Score thresholds (max 100)
  hotAt: 70,
  warmAt: 40,
};
// ================================================

const lead = $input.first().json;
const text = [lead.message, lead.budget, lead.timeline, lead.company_size, lead.company]
  .join(' ').toLowerCase();
const any = (patterns, ...fields) => patterns.some(r => fields.some(f => r.test(f || '')));
const reasons = [];
let budget = 0, timeline = 0, fit = 0, size = 0;

// Budget (0-30)
if (any(CONFIG.budgetStrong, text, lead.budget)) { budget = 30; reasons.push('Budget: strong signal'); }
else if (any(CONFIG.budgetMid, text, lead.budget)) { budget = 18; reasons.push('Budget: mid-range'); }
else if (lead.budget) { budget = 12; reasons.push(`Budget: stated but unclear ("${lead.budget}")`); }
else { budget = 6; reasons.push('Budget: not mentioned'); }

// Timeline (0-25)
if (any(CONFIG.timelineUrgent, text, lead.timeline)) { timeline = 25; reasons.push('Timeline: urgent'); }
else if (any(CONFIG.timelineNear, text, lead.timeline)) { timeline = 15; reasons.push('Timeline: near-term'); }
else if (any(CONFIG.timelineCold, text, lead.timeline)) { timeline = 4; reasons.push('Timeline: no urgency'); }
else { timeline = lead.timeline ? 12 : 8; reasons.push('Timeline: neutral'); }

// Fit (0-25)
const hits = CONFIG.fitKeywords.filter(k => text.includes(k));
fit = hits.length >= 3 ? 25 : hits.length === 2 ? 18 : hits.length === 1 ? 12 : 4;
reasons.push(hits.length ? `Fit: ${hits.slice(0, 4).join(', ')}` : 'Fit: no service keywords');

// Company size (0-20)
if (/\b([5-9]\d|\d{3,})\s*(employees|people|staff)/i.test(text) || /funded|series [a-c]|enterprise/i.test(text)) size = 20;
else if (/\b([1-4]\d)\s*(employees|people|staff)/i.test(text) || /startup|small team|agency/i.test(text)) size = 14;
else size = lead.company ? 8 : 5;
reasons.push(`Company size: ${size}/20`);

let score = budget + timeline + fit + size;
const dq = CONFIG.disqualifiers.find(d => text.includes(d));
if (dq) { score = Math.min(score, 20); reasons.push(`Disqualifier: "${dq}" (capped at 20)`); }

const temperature = score >= CONFIG.hotAt ? 'Hot' : score >= CONFIG.warmAt ? 'Warm' : 'Cold';
const priority = temperature === 'Hot' ? 'P1: reply today' : temperature === 'Warm' ? 'P2: reply within 48h' : 'P3: nurture / polite decline';

return [{ json: { ...lead, score, temperature, priority,
  score_breakdown: { budget, timeline, fit, company_size: size }, score_reasons: reasons } }];
